	under_1s: number;
  /** Count of stream requests observed between 101ms and 500ms. */
	under_500ms: number;
  /** Count of stream requests observed between 11ms and 50ms. */
	under_50ms: number;
  /** Count of stream requests observed between 2ms and 5ms. */
